			/**
			 * 목록화면에서 전달받은 정보구성
			 ** @param {"CREATE" | "READ"} psType 게시글 상세 조회 타입
			 * @param {any} poData 데이터
			 */
			function setDtlData(psType, poData) {
			    var dsDayCheckList = app.lookup("dsDayChckList");
			    var dsFcltyChckList = app.lookup("dsFcltyChckList");
			    var dsFireChckList = app.lookup("dsFireChckList");
			    var dsSnitatMngList = app.lookup("dsSnitatMngList");
			    var voDmDtlParam = app.lookup("dmDtlParam");
			    
			    // 전달받은 데이터맵 빌드
			    voDmDtlParam.build(poData);
			    app.lookup("dmDtlParamOrigin").build(poData);
			    originWrtYmd = voDmDtlParam.getValue("WRT_YMD");
			    
			    //등록 시
			    if (psType == "CREATE") {
			        psTypeStatus = "CREATE";
			//        voDmDtlParam.clear();
			        app.lookup("dti1").value = moment().format('YYYYMMDD');
			        
			        dsDayCheckList.clear();
			        dsFcltyChckList.clear();
			        dsFireChckList.clear();
			        dsSnitatMngList.clear();
			        
			        util.Submit.send(app, "subOnload", function(pbSuccess) {
			            setInitSelect(poData);
			            
			            util.Submit.send(app, "subList", function(pbSuccess){
			                app.lookup("grpData").redraw();
			                app.lookup("grpSearch").redraw();
			                //작성일자 셋팅
			                voDmDtlParam.setValue("WRT_YMD", app.lookup("dti1").value);
			            });
			        });
			        setDtlCrud(psType);
			        
			    } else if (psType == "READ") {
			        psTypeStatus = "READ";
			        createYn = false;
			        util.Submit.send(app, "subOnload", function(pbSuccess) {
			            doList();
			            setDtlCrud(psType);
			        });
			    }
			}
			exports.setDtlData = setDtlData;


			/**
			 * CRUD 권한에 따른 화면 구성
			 ** @param {"CREATE" | "READ" | "UPDATE"} psType 게시글 상세 조회 타입
			 */
			function setDtlCrud(psType, nightYnArr) {
			    
			    var voHostApp = app.getHostAppInstance();
			    
			    if (psType == "READ") {
			        util.Control.setVisible(app, false, ["btn3", "btn6"]);
			        util.Control.setVisible(app, true, ["btn4", "btn7", "grp1"]);
			        util.Control.setEnable(app, false, ["grpSearch"]);
			        util.Control.setReadOnly(app, true, ["grpData"]);
			        util.Control.setEnable(app, false, ["grp2"]);
			        
			        var flag = false;
			        app.lookup("dsPic").forEachOfUnfilteredRows(function(dataRow){
			            if((dataRow.getValue("TKCG_RELM_SE_CD") == '07' || dataRow.getValue("TKCG_RELM_SE_CD") == '08')
			                && dataRow.getValue("SRVC_EXCN_BIZ_NO") == app.lookup("dmDtlParam").getValue("SRVC_EXCN_BIZ_NO")
			                && dataRow.getValue("ALTMNT_GROUP_SCLAS_SE_CD") == app.lookup("dmDtlParam").getValue("ALTMNT_GROUP_SCLAS_SE_CD")){
			                flag = true;
			            }
			            if(flag == true){
			                return;
			            }
			        });
			        
			        if(flag){
			            app.lookup("btn4").visible = true;
			        }else{
			            app.lookup("btn4").visible = false;
			        }
			        
			    } else if(psType == "UPDATE"){
			        util.Control.setEnable(app, true, ["grpSearch"]);
			        util.Control.setReadOnly(app, false, ["grpData"]);
			        util.Control.setVisible(app, true, ["btn3", "btn6", "grp1"]);
			        util.Control.setVisible(app, false, ["btn4", "btn7"]);
			        util.Control.setEnable(app, false, ["grp2"]);
			        
			        //야간 A있을땐 B에 로그인한 담당자 세팅, 야간 B있을땐 A에 로그인한 담당자 세팅
			        if((app.lookup("cmb4"). value == null || app.lookup("cmb4"). value == '')
			            && nightYnArr[0] == true){
			            app.lookup("cmb4").selectItemByValue(user.getUserInfo(app, "ENFSN_NO"));
			        }else if((app.lookup("cmb6"). value == null || app.lookup("cmb6"). value == '')
			            && nightYnArr[1] == true){
			            app.lookup("cmb6").selectItemByValue(user.getUserInfo(app, "ENFSN_NO"));
			        }
			        
			    } else if (psType == "CREATE") {
			        util.Control.setEnable(app, true, ["grpSearch"]);
			        util.Control.setReadOnly(app, false, ["grpData"]);
			        util.Control.setEnable(app, true, ["grp2"]);
			        
			        util.Control.setVisible(app, true, ["btn3"]);
			        util.Control.setVisible(app, false, ["btn4", "btn6"]);
			        
			    } 
			    util.Control.redraw(app, "grpData");
			    app.lookup("grpSearch").redraw();
			}

