			function checkNightPic(){
			    var tkcgArr = [];
			    app.lookup("dmDtlParam").setValue("SRVC_EXCN_BIZ_NO", app.lookup("cmb2").value);
			    app.lookup("dmDtlParam").setValue("ALTMNT_GROUP_SCLAS_SE_CD", app.lookup("cmb3").value);
			    
			    var nightA = false;
			    var nightB = false;
			    
			    var nightYnArr = [];
			    
			    if(app.lookup("cmb2").value == '' || app.lookup("cmb3").value == ''){
			        return false;
			    }

			    app.lookup("dsPic").forEachOfUnfilteredRows(function(dataRow){
			        if((dataRow.getValue("TKCG_RELM_SE_CD") == '07' || dataRow.getValue("TKCG_RELM_SE_CD") == '08')
			            && dataRow.getValue("SRVC_EXCN_BIZ_NO") == app.lookup("dmDtlParam").getValue("SRVC_EXCN_BIZ_NO")
			            && dataRow.getValue("ALTMNT_GROUP_SCLAS_SE_CD") == app.lookup("dmDtlParam").getValue("ALTMNT_GROUP_SCLAS_SE_CD")
			            && dataRow.getValue("PIC_NO") == user.getUserInfo(app,"ENFSN_NO")){
			            tkcgArr.push(dataRow.getValue("TKCG_RELM_SE_CD"));
			        }
			    });
			    
			    if(tkcgArr.includes("07") && tkcgArr.includes("08")){
			        nightA = true;
			        nightB = true;
			        app.lookup("rdb2").readOnly = false;
			        app.lookup("rdb3").readOnly = false;
			        app.lookup("rdb11").readOnly = false;
			        app.lookup("rdb12").readOnly = false;
			        app.lookup("rdb13").readOnly = false;
			        app.lookup("rdb14").readOnly = false;
			        app.lookup("cmb4").selectItemByValue(user.getUserInfo(app, "ENFSN_NO"));
			        app.lookup("cmb6").selectItemByValue(user.getUserInfo(app, "ENFSN_NO"));
			    }
			    else if(tkcgArr.includes("07")){    //야간A담당자에 속할경우
			        if(psTypeStatus == 'CREATE'){
			            app.lookup("dsFcltyChckList").forEachOfUnfilteredRows(function(dataRow){
			                dataRow.setValue("SCD_CHCK_RESULT_SE_CD", '');
			            });
			            app.lookup("dsFireChckList").forEachOfUnfilteredRows(function(dataRow){
			                dataRow.setValue("SCD_CHCK_RESULT_SE_CD", '');
			            });
			            app.lookup("dsSnitatMngList").forEachOfUnfilteredRows(function(dataRow){
			                dataRow.setValue("SCD_CHCK_RESULT_SE_CD", '');
			            });
			        }else{
			            if(app.lookup("dsDayChckList").getValue(0, "NIGHT_PIC_NO2") == "" 
			                || app.lookup("dsDayChckList").getValue(0, "NIGHT_PIC_NO2") == null){
			                app.lookup("cmb6").selectItemByValue("");
			            }
			        }
			        nightA = true;
			        nightB = false;
			        app.lookup("rdb3").readOnly = true;
			        app.lookup("rdb12").readOnly = true;
			        app.lookup("rdb14").readOnly = true;
			        app.lookup("rdb2").readOnly = false;
			        app.lookup("rdb11").readOnly = false;
			        app.lookup("rdb13").readOnly = false;
			        
			    }else if(tkcgArr.includes("08")){    //야간B담당자에 속할경우
			        if(psTypeStatus == 'CREATE'){
			            app.lookup("dsFcltyChckList").forEachOfUnfilteredRows(function(dataRow){
			                dataRow.setValue("TPRI_CHCK_RESULT_SE_CD", '');
			            });
			            app.lookup("dsFireChckList").forEachOfUnfilteredRows(function(dataRow){
			                dataRow.setValue("TPRI_CHCK_RESULT_SE_CD", '');
			            });
			            app.lookup("dsSnitatMngList").forEachOfUnfilteredRows(function(dataRow){
			                dataRow.setValue("TPRI_CHCK_RESULT_SE_CD", '');
			            });
			        }else{
			            if(app.lookup("dsDayChckList").getValue(0, "NIGHT_PIC_NO1") == "" 
			                || app.lookup("dsDayChckList").getValue(0, "NIGHT_PIC_NO1") == null){
			                app.lookup("cmb4").selectItemByValue("");
			            }
			        }
			        nightA = false;
			        nightB = true;
			        app.lookup("rdb2").readOnly = true;
			        app.lookup("rdb11").readOnly = true;
			        app.lookup("rdb13").readOnly = true;
			        app.lookup("rdb3").readOnly = false;
			        app.lookup("rdb12").readOnly = false;
			        app.lookup("rdb14").readOnly = false;
			    }else{
			        util.Msg.alert(app, "야간 담당자로 지정된 과정, 생활동에 대한 점검표만 작성할 수 있습니다.");
			        util.Control.setValue(app, "cmb3", '', false);
			        app.lookup("cmb2").selectItemByValue("", false);
			        app.lookup("cmb3").selectItemByValue("", false);
			        app.lookup("dsFcltyChckList").forEachOfUnfilteredRows(function(dataRow){
			            dataRow.setValue("TPRI_CHCK_RESULT_SE_CD", '');
			            dataRow.setValue("SCD_CHCK_RESULT_SE_CD", '');
			        });
			        app.lookup("dsFireChckList").forEachOfUnfilteredRows(function(dataRow){
			            dataRow.setValue("TPRI_CHCK_RESULT_SE_CD", '');
			            dataRow.setValue("SCD_CHCK_RESULT_SE_CD", '');
			        });
			        app.lookup("dsSnitatMngList").forEachOfUnfilteredRows(function(dataRow){
			            dataRow.setValue("TPRI_CHCK_RESULT_SE_CD", '');
			            dataRow.setValue("SCD_CHCK_RESULT_SE_CD", '');
			        });
			        
			        nightA = false;
			        nightB = false;
			        app.lookup("rdb2").readOnly = true;
			        app.lookup("rdb3").readOnly = true;
			        app.lookup("rdb11").readOnly = true;
			        app.lookup("rdb12").readOnly = true;
			        app.lookup("rdb13").readOnly = true;
			        app.lookup("rdb14").readOnly = true;
			    }
			    nightYnArr.push(nightA);
			    nightYnArr.push(nightB);
			    
			    return nightYnArr;
			}

			//****************************************************************************
			/**
			  * 생활동관리에 등록안된 과정 필터
			  */
			 function setSrvcExcnBizFilter() {
			     
			     var srvcExcnFilter = '';
			     
			     app.lookup("dsPic").forEachOfUnfilteredRows(function(dataRow) {
			         if (srvcExcnFilter)
			             srvcExcnFilter = srvcExcnFilter + " || ";
			         srvcExcnFilter = srvcExcnFilter + "SRVC_EXCN_BIZ_NO == '" + dataRow.getValue("SRVC_EXCN_BIZ_NO") + "'";
			     });
			     app.lookup("dsSrvcExcnBizCmb").setFilter(srvcExcnFilter);
			     
			     setAltmntGroupFilter();
			 }
			 
			 /**
			  * 생활동관리에 등록안된 생활동 필터
			  */
			 function setAltmntGroupFilter() {
			     
			     var altmntGroupFilter = '';
			     
			     app.lookup("dsPic").forEachOfUnfilteredRows(function(dataRow) {
			         if (dataRow.getValue("SRVC_EXCN_BIZ_NO") == app.lookup("cmb2").value || ValueUtil.isNull(app.lookup("cmb2").value)) {
			             if (altmntGroupFilter)
			                 altmntGroupFilter = altmntGroupFilter + " || ";
			             altmntGroupFilter = altmntGroupFilter + "CMMNS_CD_VALUE == '" + dataRow.getValue("ALTMNT_GROUP_SCLAS_SE_CD") + "'";
			         }
			     });
			//     console.log(altmntGroupFilter);
			     if (altmntGroupFilter)
			         app.lookup("dsAltmntGroupSclasSeCd").setFilter(altmntGroupFilter);
			     
			//     console.log(app.lookup("dsAltmntGroupSclasSeCd").getFilter());
			     app.lookup("grpSearch").redraw();
			 }
			 
			 
			 /**
			  * 등록시 콤보박스 초기설정
			  */
			 function setInitSelect(poData) {
			     
			     var cmbBizYr = app.lookup("cmb1");
			     var cmbInst = app.lookup("cmb5");
			     var cmbSrvcExcnBiz = app.lookup("cmb2");
			     var cmbAltmntGroup = app.lookup("cmb3");
			     
			     setSrvcExcnBizFilter();
			     
			     if(!ValueUtil.isNull(poData["BIZ_YR"]))
			        cmbBizYr.selectItemByValue(poData["BIZ_YR"]);
			     else if (cmbBizYr.getItemByValue(moment().year())) 
			        cmbBizYr.selectItemByValue(moment().year());
			     else{
			         cmbBizYr.selectItem(0);
			     }
			        
			     if(!ValueUtil.isNull(poData["INST_NO"]))
			        cmbInst.selectItemByValue(poData["INST_NO"]);
			     else if (cmbInst.getItemCount() == 2)
			        cmbInst.selectItem(1);
			     else{
			         cmbInst.selectItem(0);
			     }
			     
			     if(!ValueUtil.isNull(poData["SRVC_EXCN_BIZ_NO"]) && !ValueUtil.isNull(cmbSrvcExcnBiz.getItemByValue(poData["SRVC_EXCN_BIZ_NO"])))
			        cmbSrvcExcnBiz.selectItemByValue(poData["SRVC_EXCN_BIZ_NO"]);
			     else if (cmbSrvcExcnBiz.getItemCount() == 2)
			        cmbSrvcExcnBiz.selectItem(1);
			     else
			        cmbSrvcExcnBiz.selectItem(0);
			        
			     if(!ValueUtil.isNull(poData["ALTMNT_GROUP_SCLAS_SE_CD"])&& !ValueUtil.isNull(cmbAltmntGroup.getItemByValue(poData["ALTMNT_GROUP_SCLAS_SE_CD"])))
			        cmbAltmntGroup.selectItemByValue(poData["ALTMNT_GROUP_SCLAS_SE_CD"]);
			     else if (cmbAltmntGroup.getItemCount() == 2) 
			        cmbAltmntGroup.selectItem(1);
			     else
			        cmbAltmntGroup.selectItem(0);
			     
			     app.lookup("dti1").value = moment().format('YYYYMMDD');
			     
			     app.lookup("grpSearch").redraw();
			 }

